import playbackService from '../../services/PlaybackService.js';class RecordingCalendar{constructor(container,options={}){this.container=container;this.currentMonth=new Date();this.selectedDate=new Date();this.recordingDays=new Map();this.selectedCameraId=null;this.options={onDateSelect:null,onMonthChange:null,showWeekNumbers:false,highlightToday:true,...options};this.monthNames=[ 'January','February','March','April','May','June','July','August','September','October','November','December' ];this.dayNames=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];this.init();}init(){this.render();this.attachEventListeners();}render(){if(!this.container)return;this.container.innerHTML=this.getTemplate();this.updateMonthDisplay();this.renderCalendarDays();}getTemplate(){return ` <div class="recording-calendar"> <div class="calendar-header"> <button class="btn btn-sm btn-secondary prev-month" title="Previous Month"> <i class="fas fa-chevron-left"></i> </button> <div class="month-year-display"> <span class="month-name"></span> <span class="year-name"></span> </div> <button class="btn btn-sm btn-secondary next-month" title="Next Month"> <i class="fas fa-chevron-right"></i> </button> </div> <div class="calendar-body"> <div class="calendar-weekdays"> ${this.dayNames.map(day=> `<div class="weekday">${day}</div>`).join('')}</div> <div class="calendar-days"> <!--Days will be rendered here--> </div> </div> <div class="calendar-legend"> <div class="legend-item"> <div class="legend-indicator has-recordings"></div> <span>Has Recordings</span> </div> <div class="legend-item"> <div class="legend-indicator partial-recordings"></div> <span>Partial Coverage</span> </div> <div class="legend-item"> <div class="legend-indicator no-recordings"></div> <span>No Recordings</span> </div> <div class="legend-item"> <div class="legend-indicator selected-day"></div> <span>Selected</span> </div> </div> </div> `;}attachEventListeners(){const prevBtn=this.container.querySelector('.prev-month');const nextBtn=this.container.querySelector('.next-month');prevBtn?.addEventListener('click',()=> this.navigateMonth(-1));nextBtn?.addEventListener('click',()=> this.navigateMonth(1));const calendarDays=this.container.querySelector('.calendar-days');calendarDays?.addEventListener('click',(e)=>{const dayElement=e.target.closest('.calendar-day');if(dayElement && !dayElement.classList.contains('other-month')){const day=parseInt(dayElement.dataset.day);this.selectDate(day);}});}async loadMonth(cameraId,year=null,month=null){this.selectedCameraId=cameraId;if(year !==null && month !==null){this.currentMonth=new Date(year,month-1,1);}const currentYear=this.currentMonth.getFullYear();const currentMonthNum=this.currentMonth.getMonth()+1;try{const calendarData=await playbackService.getCalendarData(cameraId,currentYear,currentMonthNum);this.updateRecordingDays(calendarData.days ||{});this.updateMonthDisplay();this.renderCalendarDays();this.options.onMonthChange?.(currentYear,currentMonthNum,calendarData);}catch(error){console.error('Failed to load calendar data:',error);this.showError('Failed to load calendar data');}}updateRecordingDays(daysData){this.recordingDays.clear();for(const [dayStr,data] of Object.entries(daysData)){const day=parseInt(dayStr);let status='no-recordings';if(data.has_recordings){if(data.recording_percentage >=80){status='has-recordings';}else if(data.recording_percentage > 0){status='partial-recordings';}}this.recordingDays.set(day,{...data,status});}}updateMonthDisplay(){const monthNameEl=this.container.querySelector('.month-name');const yearNameEl=this.container.querySelector('.year-name');if(monthNameEl){monthNameEl.textContent=this.monthNames[this.currentMonth.getMonth()];}if(yearNameEl){yearNameEl.textContent=this.currentMonth.getFullYear().toString();}}renderCalendarDays(){const calendarDays=this.container.querySelector('.calendar-days');if(!calendarDays)return;const year=this.currentMonth.getFullYear();const month=this.currentMonth.getMonth();const firstDay=new Date(year,month,1);const lastDay=new Date(year,month+1,0);const daysInMonth=lastDay.getDate();const startDayOfWeek=firstDay.getDay();const prevMonth=new Date(year,month-1,0);const daysInPrevMonth=prevMonth.getDate();let daysHtml='';for(let i=startDayOfWeek-1;i >=0;i--){const day=daysInPrevMonth-i;daysHtml+=this.getDayTemplate(day,'other-month prev-month');}for(let day=1;day <=daysInMonth;day++){const classes=[];const today=new Date();const isToday=this.options.highlightToday && year===today.getFullYear()&& month===today.getMonth()&& day===today.getDate();if(isToday)classes.push('today');const isSelected=year===this.selectedDate.getFullYear()&& month===this.selectedDate.getMonth()&& day===this.selectedDate.getDate();if(isSelected)classes.push('selected');const recordingData=this.recordingDays.get(day);if(recordingData){classes.push(recordingData.status);}daysHtml+=this.getDayTemplate(day,classes.join(' '),recordingData);}const totalCells=42;const cellsUsed=startDayOfWeek+daysInMonth;const nextMonthDays=totalCells-cellsUsed;for(let day=1;day <=nextMonthDays;day++){daysHtml+=this.getDayTemplate(day,'other-month next-month');}calendarDays.innerHTML=daysHtml;}getDayTemplate(day,classes='',recordingData=null){const hasRecordings=recordingData && recordingData.has_recordings;const coverage=recordingData ? Math.round(recordingData.recording_percentage || 0):0;const totalSize=recordingData ? playbackService.formatFileSize(recordingData.total_size || 0):'';const duration=recordingData ? playbackService.formatDuration(recordingData.total_duration || 0):'';const title=hasRecordings ? `${coverage}% coverage,${duration}recorded,${totalSize}`:'No recordings';return ` <div class="calendar-day ${classes}" data-day="${day}" title="${title}"> <span class="day-number">${day}</span> ${hasRecordings ? ` <div class="recording-indicator"> <div class="coverage-bar"> <div class="coverage-fill" style="width:${coverage}%"></div> </div> <div class="coverage-text">${coverage}%</div> </div> `:''}</div> `;}navigateMonth(direction){const newMonth=new Date(this.currentMonth);newMonth.setMonth(newMonth.getMonth()+direction);this.currentMonth=newMonth;if(this.selectedCameraId){this.loadMonth(this.selectedCameraId);}else{this.updateMonthDisplay();this.renderCalendarDays();}}selectDate(day){const year=this.currentMonth.getFullYear();const month=this.currentMonth.getMonth();this.selectedDate=new Date(year,month,day);this.renderCalendarDays();this.options.onDateSelect?.(this.selectedDate,this.recordingDays.get(day));}setSelectedDate(date){this.selectedDate=new Date(date);if(date.getFullYear()!==this.currentMonth.getFullYear()|| date.getMonth()!==this.currentMonth.getMonth()){this.currentMonth=new Date(date.getFullYear(),date.getMonth(),1);if(this.selectedCameraId){this.loadMonth(this.selectedCameraId);}else{this.updateMonthDisplay();this.renderCalendarDays();}}else{this.renderCalendarDays();}}getSelectedDate(){return new Date(this.selectedDate);}getCurrentMonth(){return{year:this.currentMonth.getFullYear(),month:this.currentMonth.getMonth()+1};}getRecordingDataForDay(day){return this.recordingDays.get(day)|| null;}showError(message){console.error('RecordingCalendar:',message);}destroy(){this.container.innerHTML='';}}export default RecordingCalendar;